// The Hub as a place: circulation, businesses and the crews working from it.
export const hubEnglish = {};
const L = (fr, en) => { hubEnglish[fr.replace(/\s+/g, ' ').trim()] = en; return fr; };

export const hubCopy = {
  welcome: L('Bienvenue au Hub', 'Welcome to the Hub'),
  contents: L('Se repérer dans le Hub', 'Finding your way around the Hub'),
  placesTitle: L('Comptoirs, boutiques et rendez-vous', 'Counters, shops and meeting places'),
  placesIntro: L('Les grandes enseignes occupent les façades les plus visibles, mais les habitués finissent par donner rendez-vous devant un atelier, une table ou un escalier. Ces adresses représentent quelques points d’appui dans un marché beaucoup plus vaste. On peut en connaître une seule, y faire ses achats pendant des années et ne jamais avoir affaire aux autres.', 'The biggest brands occupy the most visible frontages, but regulars eventually arrange to meet outside a workshop, at a table or by a staircase. These addresses are a few footholds in a much larger market. Someone may know just one, shop there for years and never deal with the others.'),
  crewsTitle: L('Crews en activité', 'Active crews'),
  crewsIntro: L('Un nom de crew finit par tenir lieu de carte de visite. Certains portent celui de la personne qui signe les contrats ; d’autres viennent d’un ancien indicatif ou d’un métier. Les huit équipes suivantes passent régulièrement par le Hub. Elles n’en constituent ni le classement officiel ni l’élite obligatoire : leurs clientèles, leurs moyens et leurs réputations se recoupent sans se confondre. Une équipe que l’on admire peut devenir un concurrent gênant, puis un renfort dont on se souviendra longtemps.', 'A crew’s name eventually becomes its calling card. Some use the name of the person signing contracts; others come from an old call sign or a trade. The following eight teams regularly pass through the Hub. They form neither an official ranking nor an obligatory elite: their clients, resources and reputations overlap without being identical. A team people admire can become an awkward competitor, then a reinforcement they remember for years.'),
  members: L('Les membres', 'The members'),
  work: L('Leur manière de travailler', 'How they work'),
  limits: L('Leurs limites', 'Their limits'),
  habit: L('Au retour', 'On return'),
  encounter: L('Une rencontre possible', 'A possible encounter'),
};

export const hubSections = [
  { id: 'hub-circulation', title: L('Entrer, circuler, retrouver quelqu’un', 'Arriving, getting around and finding someone'), paragraphs: [
    L('Le Hub se comprend d’abord par ses flux. Les entrées publiques débouchent sur les galeries de vente et les tableaux de contrats ; les rampes et les monte-charges amènent le fret vers les réserves. Entre les deux, des coursives permettent de traverser le marché sans passer par chaque boutique. Les habitués donnent le nom d’une enseigne et celui de l’accès le plus proche. Une adresse réduite à « au Hub » ne permet guère de retrouver quelqu’un.', 'The Hub is easiest to understand through its flows. Public entrances lead to shopping galleries and contract boards; ramps and freight lifts carry goods towards stockrooms. Walkways between them allow people to cross the market without entering every shop. Regulars give a business name and the nearest entrance. An address consisting only of “at the Hub” is of little use when finding someone.'),
    L('Dans les galeries hautes, les vitrines montrent des corps augmentés, des armures et des drones en démonstration. Plus près des accès de fret, les chariots attendent devant des ateliers qui travaillent portes ouvertes. Les pensions, les cuisines et les salles de briefing occupent les espaces moins visibles. Les odeurs de soupe, de lubrifiant et de désinfectant changent à chaque passage. Rien de tout cela n’empêche de venir avec un ami, de comparer trois produits et de repartir sans contrat.', 'In the upper galleries, displays show augmented bodies, armor and demonstration drones. Near the freight entrances, trolleys wait outside workshops working with their doors open. Boarding rooms, kitchens and briefing spaces occupy less visible areas. The smells of soup, lubricant and disinfectant change from passage to passage. None of this prevents someone from coming with a friend, comparing three products and leaving without a job.'),
  ] },
  { id: 'hub-contrats', title: L('La Halle des contrats', 'The Contract Hall'), paragraphs: [
    L('La Halle rassemble des tableaux d’offres, des bureaux loués à la journée et des alcôves où l’on peut enfin entendre son interlocuteur. Une annonce publique donne une tâche, un contact et assez de conditions pour décider d’en savoir plus. Les missions discrètes passent plutôt par les fixeurs, les recommandations ou les rendez-vous déjà pris. Les plus gros écrans ne proposent pas nécessairement les meilleures affaires : les clients sérieux ont parfois un simple créneau chez un intermédiaire qu’ils connaissent.', 'The Hall brings together job boards, offices rented by the day and alcoves where people can finally hear each other speak. A public listing gives a task, a contact and enough terms to decide whether to learn more. Discreet work tends to come through fixers, recommendations or arranged meetings. The biggest screens do not necessarily carry the best deals: serious clients sometimes have only an appointment with a broker they know.'),
    L('Avant de partir, on précise qui commande, ce qui doit être livré, ce qui permet d’attester la mission et comment chacun sera payé. Le Syndicat propose ses services de représentation et d’arbitrage ; il ne signe pas toutes les affaires du marché. Les rémunérations en chroma sont attribuées aux comptes prévus au contrat et dépensées dans le circuit agréé. Le dîner, le loyer d’une chambre ou les courses ordinaires se règlent autrement. Cette différence fait partie du quotidien des crews : un bon contrat peut améliorer l’équipement sans remplir le réfrigérateur.', 'Before departure, people establish who is hiring, what must be delivered, how completion will be evidenced and how each participant will be paid. The Syndicate offers representation and arbitration; it does not sign every deal in the market. Chroma payments go to the accounts specified by the contract and are spent within the licensed circuit. Dinner, room rent and everyday shopping are paid for differently. Crews live with that distinction: a good job may improve their equipment without filling the refrigerator.'),
  ] },
  { id: 'hub-preparation', title: L('Acheter une capacité, préparer un départ', 'Buying a capability, preparing to leave'), paragraphs: [
    L('Les comptoirs des huit fondateurs côtoient les revendeurs indépendants et les spécialistes qui ne travaillent que sur quelques références. Une crew peut acheter une arme Bastion, essayer une augmentation Biolux dans une clinique indépendante et louer un drone avant de chercher un véhicule. Les installations importantes donnent lieu à un rendez-vous, à des essais et parfois à une convalescence. Les vendeurs parlent volontiers du résultat promis ; les équipes expérimentées demandent aussi qui assurera le suivi une fois le produit sorti de la vitrine.', 'Counters operated by the eight founders stand beside independent retailers and specialists working on only a few product lines. A crew may buy a Bastion weapon, try a Biolux augmentation at an independent clinic and rent a drone before looking for a vehicle. Major installations involve appointments, tests and sometimes recovery time. Sellers readily discuss the promised result; experienced teams also ask who will provide support once the product leaves the display.'),
    L('On réserve une table pour le briefing, on étale un plan, on récupère les achats et l’on vérifie les liaisons. Les casiers évitent de transporter toute sa vie pendant chaque négociation. Aux départs, un équipier compte les sacs tandis qu’un autre revient chercher un chargeur oublié. Les grandes équipes emploient parfois quelqu’un pour cette préparation ; les plus petites se répartissent le travail en mangeant debout.', 'People book a briefing table, spread out a plan, collect purchases and check communications. Lockers save them from carrying their whole lives into every negotiation. At departure, one teammate counts bags while another goes back for a forgotten charger. Larger teams sometimes employ someone to handle preparation; smaller ones divide the work while eating on their feet.'),
  ] },
  { id: 'hub-retours', title: L('Les heures du retour', 'The hours after returning'), paragraphs: [
    L('Le Hub ne vit pas au rythme d’une seule journée de travail. Des équipes arrivent couvertes de poussière quand d’autres essaient leur tenue neuve ; les cuisines servent ceux qui viennent de finir autant que ceux qui commencent. Après une mission, il faut remettre le chargement, faire constater le résultat, soigner les blessures et attendre parfois le règlement. Les récits passent ensuite d’une table à l’autre, souvent un peu plus nets et un peu plus héroïques à chaque reprise.', 'The Hub does not follow a single working day. Teams arrive covered in dust while others try on new equipment; kitchens feed people finishing work as well as those starting. After a mission come the handover, confirmation of completion, treatment of injuries and sometimes a wait for payment. Stories then pass from table to table, usually a little cleaner and more heroic with each retelling.'),
    L('C’est aussi là que l’on voit les places vides. Une crew attend des nouvelles d’une clinique, une autre cherche de quoi payer une extraction, une troisième fête simplement le fait d’être rentrée au complet. Le Grand Soir accueille une part de ces retours, mais chaque équipe garde ses habitudes : une soupe, un lit, un atelier tranquille ou le besoin de quitter le marché pendant quelques jours. On peut vivre du Hub sans vouloir y passer toute sa vie.', 'It is also where empty places become visible. One crew waits for news from a clinic, another looks for ways to fund an extraction and a third simply celebrates everyone coming home. Le Grand Soir hosts some of these returns, but every team has its habits: soup, a bed, a quiet workshop or a need to leave the market for a few days. People can make a living from the Hub without wanting to spend their whole lives there.'),
  ] },
];

export const hubStops = [
  { id: 'grand-soir', name: L('Le Grand Soir', 'Le Grand Soir'), role: L('Cantine, bar et maison de retour · à la lisière du marché', 'Canteen, bar and gathering place after missions · at the market’s edge'), art: 'syndicat-bd', scene: 0, panels: 3,
    paragraphs: [
      L('Le Grand Soir occupe la lisière du Hub, assez près pour y finir un briefing et assez en retrait pour que le vacarme des démonstrations s’efface derrière les conversations. La cuisine reste son premier point d’attraction : plats chauds, longues tables et chaises que l’on rapproche quand un équipier arrive en retard. Le soir, les parties, les retransmissions et les discussions se prolongent autour du bar. Les habitués savent où s’installer pour être vus et quelles tables laisser à ceux qui veulent parler bas.', 'Le Grand Soir stands at the edge of the Hub, close enough to finish a briefing there and far enough back for conversation to replace the noise of demonstrations. Its kitchen is the first attraction: hot meals, long tables and chairs drawn up when a teammate arrives late. In the evening, games, broadcasts and conversations continue around the bar. Regulars know where to sit to be seen and which tables to leave to people speaking quietly.'),
      L('Le Syndicat y tient une présence, reçoit les membres et encadre une partie des affaires. Les invités viennent avec quelqu’un ou sont présentés ; les armes sont sécurisées à l’entrée. Le mur des disparus accueille les photographies et les nouvelles de ceux qui manquent. Une veillée peut y commencer sans faire taire toute la salle. Le Grand Soir compte pour les crews qui le fréquentent, mais il ne remplace ni les cliniques, ni les tribunaux, ni les décisions communes du Hub.', 'The Syndicate maintains a presence, meets members and oversees some business there. Guests arrive with someone or are introduced; weapons are secured at the entrance. The wall of the missing holds photographs and news of absent people. A vigil can begin without silencing the whole room. Le Grand Soir matters to the crews who use it, but it replaces neither clinics, courts nor the Hub’s shared decisions.'),
    ], links: ['zone-grand-soir'] },
  { id: 'havel', name: L('Havel — armurerie et réglage', 'Havel — armory and fitting'), role: L('Comptoir indépendant agréé · armes, protections et essais', 'Independent licensed counter · weapons, protection and testing'),
    paragraphs: [
      L('À l’armurerie Havel, les armes d’essai sont alignées derrière une vitre qui porte les traces de doigts des clients. Rena Havel commence par faire épauler un modèle déchargé avant de parler de finition ou d’accessoires. Elle distribue plusieurs fabricants, dont Bastion, et connaît assez bien son stock pour reconnaître le bruit d’un mécanisme mal remonté. Une courte galerie d’essai, réservée par créneau, permet de vérifier une prise en main et un réglage sans transformer le marché en stand de tir.', 'At Havel’s armory, trial weapons stand behind glass marked by customers’ fingerprints. Rena Havel begins by having someone shoulder an unloaded model before discussing finishes or accessories. She stocks several manufacturers, including Bastion, and knows her inventory well enough to recognize the sound of a badly reassembled mechanism. A short testing lane, booked by time slot, allows handling and adjustments to be checked without turning the market into a firing range.'),
      L('Elle vend les références du catalogue et traite les achats éligibles en chroma. Un retour suit la garantie et recrédite le compte d’origine ; une arme volée ne devient pas un remboursement grâce à une bonne histoire. Havel recommande volontiers un modèle moins cher quand il convient mieux, mais déteste qu’un client revienne lui attribuer une capacité qu’elle n’a jamais promise. Elle cherche actuellement une équipe pour récupérer des caisses de pièces retenues dans un dépôt après la faillite d’un transporteur.', 'She sells catalogue items and processes eligible purchases in chroma. Returns follow warranty terms and credit the original account; a stolen weapon does not become a refund through a convincing story. Havel readily recommends a cheaper model when it fits better, but hates customers returning to claim she promised a capability she never mentioned. She is currently seeking a team to retrieve parts crates held in a warehouse after a carrier went bankrupt.'),
    ], links: ['chroma-catalogue'] },
  { id: 'clinique-varga', name: L('Clinique Varga', 'Varga Clinic'), role: L('Implantation, adaptation et suivi · rendez-vous médicaux', 'Implantation, fitting and follow-up · medical appointments'),
    paragraphs: [
      L('La clinique ouvre derrière une réception claire, séparée des galeries par deux portes qui coupent enfin le bruit. Le docteur Emil Varga reçoit autant les premières demandes que les anciens patients venus faire contrôler une gêne. Son équipe travaille avec les produits de plusieurs fabricants, dont Helix et Biolux, selon les compatibilités et les compétences disponibles. Les démonstrations restent dans la salle d’essai ; les décisions médicales se prennent en consultation.', 'The clinic opens behind a bright reception area, separated from the galleries by two doors that finally shut out the noise. Dr Emil Varga sees first-time clients as well as former patients returning to check a problem. His team works with products from several manufacturers, including Helix and Biolux, according to compatibility and available expertise. Demonstrations stay in the trial room; medical decisions are made in consultation.'),
      L('Les patients parlent volontiers de ce qu’ils pourront faire après l’intervention. Varga leur demande aussi comment ils rentreront chez eux et qui couvrira leurs prochains jours de repos. Les prestations agréées peuvent être réglées dans le circuit chroma ; cela ne dispense ni de l’examen ni du suivi. La clinique stabilise les urgences qu’elle sait traiter et organise les transferts nécessaires. Elle ne possède pas de centre de résurrection et ne promet pas de reconstruire quelqu’un entre deux rendez-vous.', 'Patients readily discuss what they will be able to do after a procedure. Varga also asks how they will get home and who will cover their next few days of rest. Licensed services can be paid through the chroma circuit; this waives neither examination nor follow-up. The clinic stabilizes emergencies it can treat and arranges necessary transfers. It has no resurrection center and does not promise to reconstruct someone between appointments.'),
    ], links: ['tech-biotech', 'tech-memoire'] },
  { id: 'azimut', name: L('Azimut', 'Azimut'), role: L('Drones, capteurs et liaisons de terrain', 'Drones, sensors and field communications'),
    paragraphs: [
      L('De petits drones suivent des parcours derrière le filet du plafond, au-dessus de caisses de capteurs et de télécommandes. Youn Marek, propriétaire d’Azimut, laisse les clients essayer une interface avant de leur montrer les fonctions avancées. Son commerce indépendant vend et entretient des appareils de plusieurs gammes ; les services Synapse n’y sont qu’une partie des équipements et abonnements disponibles. Le Raccord lui adresse les réparations qui exigent son banc radio, et il lui renvoie les adaptations de connectique.', 'Small drones follow routes behind ceiling netting, above cases of sensors and controllers. Azimut’s owner, Youn Marek, lets customers try an interface before showing its advanced functions. His independent business sells and services devices from several product lines; Synapse services are only part of the available equipment and subscriptions. The Coupling refers repairs requiring his radio bench, and he sends connector adaptations back their way.'),
      L('Marek insiste sur les angles morts, les batteries et les pertes de liaison. Ses drones exécutent des programmes ; ils n’acquièrent pas une volonté personnelle parce qu’un client leur a donné un prénom. Une démonstration au Hub ne garantit pas les mêmes performances sous des tonnes de béton. Il prête parfois un exemplaire à Romy pour un essai annoncé comme tel, puis lit ses critiques avec une mauvaise humeur qui ne l’empêche pas de corriger le produit.', 'Marek stresses blind spots, batteries and lost connections. His drones execute programs; they do not gain personal wills because a customer gave them names. A demonstration at the Hub does not guarantee equal performance beneath tons of concrete. He sometimes lends Romy a unit for a disclosed review, then reads her criticism with an ill temper that does not prevent him from correcting the product.'),
    ], links: ['pnj-romy-saad', 'tech-drones'] },
  { id: 'quai-depart', name: L('Le Quai des départs', 'The Departure Bay'), role: L('Fret, consignes et rendez-vous avec les transporteurs', 'Freight, lockers and meetings with carriers'),
    paragraphs: [
      L('Le Quai des départs est une aire de chargement intérieure reliée aux accès routiers du Hub ; ce n’est pas un quai du fleuve. Les équipes attendent leurs véhicules entre des emplacements numérotés, des consignes et un bureau d’expédition. Les départs vers les Docks enfouis y rejoignent les tournées de livraison ordinaires. À chaque prise en charge, on compte les personnes et les colis, puis quelqu’un doit encore aller chercher le dernier équipier.', 'The Departure Bay is an indoor loading area connected to the Hub’s road entrances, not a river quay. Teams wait for vehicles among numbered bays, lockers and a dispatch office. Departures for the Buried Docks mingle with ordinary delivery runs. At every handover, people and packages are counted, then someone still has to fetch the last teammate.'),
      L('Farid Noam répartit les emplacements de son service, pas tous les transports de Paradise. Il sait quel chauffeur accepte une charge encombrante et qui facture l’attente à partir de la première minute. Une réservation donne une place et un horaire ; elle n’accorde aucun laissez-passer pour la suite du trajet. Les crews reviennent vers lui parce qu’il annonce les retards avant de promettre l’impossible, et parce qu’un sac oublié finit généralement dans une consigne plutôt que chez un revendeur.', 'Farid Noam allocates bays during his shift, not all transport in Paradise. He knows which driver accepts bulky loads and who charges waiting time from the first minute. A booking grants a space and a time, not clearance for the rest of the journey. Crews return because he announces delays before promising the impossible, and because a forgotten bag usually ends up in a locker rather than with a reseller.'),
    ], links: ['zone-docks-bas'] },
];

